"""Generate `nf3g_approved_changes.json`: the explicitly approved NF-3G change to the NF-3B oscillation-selection baseline (not a test module).

NF-3G (owner decision O-9, 2026-11-28): the sub-synchronous comparison of an oscillation cross-signal component no longer uses the FIRST member's
frequency. Members that agree use the agreed frequency; members that DISAGREE yield `nominal_frequency_mixed` limiting evidence and no frequency
at all. The frozen record (`nf3b_frozen_baselines.json`, group `oscillation_selection`) stays historical. This script computes the structured
difference between "history + earlier approved changes" and the code under test, REFUSES anything that is not one of the kinds below, and
writes the rest as reviewable entries.

Kinds (everything else aborts generation):

* `nominal_comparison_withheld` -- a disagreeing-member case loses what needed ONE nominal value: the `higher_frequency_oscillatory_component`
  descriptor, the `frequency_alone_not_sso` / `nominal_frequency_assumed` evidence and the nominal values quoted in evidence.
* `nominal_frequency_mixed_reported` -- the `limiting` evidence of a disagreeing-member case now lists `nominal_frequency_mixed`.

Guard rails enforced here: only the cases whose members disagree may change; `probable_type` and `supporting` evidence never change (valid
independent signal-analysis results are preserved); agreeing, missing-value and single-declaration cases are unchanged.

Run from `backend/`:  python tests/fixtures/nf3g_baselines/generate_nf3g_approved_changes.py
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

BACKEND = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(BACKEND))

from tests import nf3b_baseline_scenarios as scenarios  # noqa: E402
from tests import nf3c_approved_changes as approved  # noqa: E402
from tests.nf3d_diff_tools import structured_diff  # noqa: E402

OUT = Path(__file__).with_name("nf3g_approved_changes.json")
#: The cases whose members declare different frequencies (the only ones O-9 may change).
DISAGREEING = {"first_50_second_60", "first_60_second_50", "first_assumed_second_manual_like_60"}


def main() -> None:
    baseline = json.loads((BACKEND / "tests/fixtures/nf3b_baselines/nf3b_frozen_baselines.json").read_text(encoding="utf-8"))
    expected = approved.apply_approved(baseline, "nf3b_frozen_baselines", include_nf3g=False)["oscillation_selection"]
    current = scenarios.run_oscillation_selection_scenarios()
    entries = []
    limiting_cases: set[tuple[str, str]] = set()
    for path, before, after in structured_diff(expected, current, ("oscillation_selection",)):
        group, case, field = path[1], path[2], path[4]
        if case not in DISAGREEING:
            raise SystemExit(f"a case whose members AGREE changed: {path}")
        if field in {"probable_type", "supporting"}:
            raise SystemExit(f"an independent result changed: {path}")
        if field in {"descriptors", "nominal_values_in_evidence"}:
            if after != []:
                raise SystemExit(f"unexpected new content at {path}: {after!r}")
            kind = "nominal_comparison_withheld"
        elif field == "limiting":
            limiting_cases.add((group, case))
            kind = "nominal_frequency_mixed_reported"
        else:
            raise SystemExit(f"UNCLASSIFIED difference: {path} {before!r} -> {after!r}")
        entries.append({"path": list(path), "before": before, "after": after, "kind": kind})
    # case-level check of the `limiting` lists (element-wise diffs of a re-ordered list are only meaningful together)
    for group, case in sorted(limiting_cases):
        old = set(expected[group][case]["returns"]["limiting"])
        new = set(current[group][case]["returns"]["limiting"])
        if new - old != {"nominal_frequency_mixed"} or not (old - new) <= {"frequency_alone_not_sso", "nominal_frequency_assumed"}:
            raise SystemExit(f"{group}/{case}: added {sorted(new - old)}, removed {sorted(old - new)}")
    OUT.write_text(json.dumps({
        "purpose": "The approved NF-3G (O-9) change to the NF-3B oscillation-selection baseline; applied after the NF-3F overlay. Generated by "
                   "generate_nf3g_approved_changes.py; every entry has a kind and only disagreeing-member cases may change.",
        "schema": 1,
        "kinds": ["nominal_comparison_withheld", "nominal_frequency_mixed_reported"],
        "changes": {"nf3b_frozen_baselines": entries},
    }, indent=1, sort_keys=True) + "\n", encoding="utf-8")
    kinds = {}
    for entry in entries:
        kinds[entry["kind"]] = kinds.get(entry["kind"], 0) + 1
    print(len(entries), kinds)


if __name__ == "__main__":
    main()
